// Only the active patrol area is expanded into world polygons. Keeping a
// one-entry cache is intentional: ten processed island sets plus ten Bathy
// grids would waste startup time and RAM on the 4 GB Helios G88. Raw compact
// coastline literals stay cheap; changing patrol area releases the old array.
let _patrolTerrainCacheKey=null,_patrolTerrainCache=null;
function getPatrolTerrain(areaKey){
  if(_patrolTerrainCacheKey===areaKey&&_patrolTerrainCache)return _patrolTerrainCache;
  _patrolTerrainCacheKey=areaKey;_patrolTerrainCache=buildTerrain(areaKey);
  if(typeof Bathy!=='undefined'){Bathy.ref=null;Bathy.data=null;}
  return _patrolTerrainCache;
}

// Natural Earth 10m coastlines (public domain), clipped to each patrol area and
// simplified to 0.3 nm. Islands carry their real names and summit heights.
function buildTerrain(areaKey){
  const src=COASTLINES[areaKey]||[],seen=new Set();
  return src.filter(s=>{const key=`${s.n}|${s.pk}|${s.a}|${(s.p||[]).join(',')}`;if(seen.has(key))return false;seen.add(key);return true;}).map((s,i)=>{
    const base=[];for(let j=0;j<s.p.length;j+=2)base.push({xNm:s.p[j],yNm:s.p[j+1]});
    const pts=[];let seed=(Number(s.seed)||((i+1)*2654435761))>>>0;
    const rnd=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
    for(let j=0;j<base.length;j++){
      const a=base[j],b=base[(j+1)%base.length],dx=b.xNm-a.xNm,dy=b.yNm-a.yNm,L=Math.hypot(dx,dy),n=s.j?Math.min(8,Math.max(1,Math.ceil(L/9))):1;
      for(let q=0;q<n;q++){const t=q/n,fade=Math.sin(Math.PI*t),off=(rnd()-.5)*2*Number(s.j||0)*fade,inv=1/Math.max(.001,L);
        pts.push({xNm:a.xNm+dx*t-dy*inv*off,yNm:a.yNm+dy*t+dx*inv*off});}
    }
    return{id:`LAND-${i}`,name:s.n,type:s.a>140?'ISLAND':s.a>12?'ISLAND':'REEF',
      depth:s.a>60?'SHOAL':'SHALLOW',peakM:s.pk,areaNm2:s.a,points:pts};
  });
}
